ALTER TABLE `version_sections` ADD `title_citations` text;--> statement-breakpoint
DROP VIEW `published_sections`;--> statement-breakpoint
CREATE VIEW `published_sections` AS select "versions"."document_id", "version_sections"."version_id", "versions"."version_no", "version_sections"."section_id", "version_sections"."parent_address", "version_sections"."address", "version_sections"."title", "version_sections"."title_citations", "version_sections"."printed_number", "version_sections"."order_index", "version_sections"."ownership", "version_sections"."point_of_care", "version_sections"."body_json", "version_sections"."html", "version_sections"."markdown", "version_sections"."last_changed_version_no" from "version_sections" inner join "versions" on "versions"."id" = "version_sections"."version_id" where (("versions"."status" = 'published') and ("version_sections"."hidden" = 0));